def match(orders):
    trades = []
    buy_book = []  # List of (price, arrival_time, id, remaining_qty)
    sell_book = []  # List of (price, arrival_time, id, remaining_qty)
    order_map = {}  # Map from id to (side, index_in_book) for tracking
    arrival_time = 0

    for order in orders:
        arrival_time += 1

        if order[0] == 'cancel':
            order_id = order[1]
            if order_id in order_map:
                side, book_index = order_map[order_id]
                if book_index is not None:
                    if side == 'buy':
                        buy_book[book_index] = None
                    else:
                        sell_book[book_index] = None
                    del order_map[order_id]

        elif order[0] in ['limit', 'ioc', 'market']:
            order_type = order[0]
            order_id = order[1]
            side = order[2]
            qty = order[-1]
            price = order[3] if order_type != 'market' else None

            order_map[order_id] = (side, None)

            if side == 'buy':
                # Match against sell book
                while qty > 0 and sell_book:
                    sell_book = [x for x in sell_book if x is not None]
                    if not sell_book:
                        break

                    best_sell = sell_book[0]
                    sell_price, sell_arrival, sell_id, sell_qty = best_sell

                    if order_type == 'market' or price >= sell_price:
                        trade_qty = min(qty, sell_qty)
                        trades.append([order_id, sell_id, sell_price, trade_qty])
                        qty -= trade_qty

                        if trade_qty == sell_qty:
                            sell_book.pop(0)
                            order_map[sell_id] = ('sell', None)
                        else:
                            sell_book[0] = (sell_price, sell_arrival, sell_id, sell_qty - trade_qty)
                    else:
                        break

                # Rest remaining quantity if limit order
                if qty > 0 and order_type == 'limit':
                    book_index = len(buy_book)
                    buy_book.append((price, arrival_time, order_id, qty))
                    order_map[order_id] = ('buy', book_index)
                    # Sort by price (descending), then by arrival time (ascending)
                    buy_book.sort(key=lambda x: (-x[0], x[1]))
                    # Update indices in order_map
                    for i, entry in enumerate(buy_book):
                        if entry is not None:
                            order_map[entry[2]] = ('buy', i)

            else:  # side == 'sell'
                # Match against buy book
                while qty > 0 and buy_book:
                    buy_book = [x for x in buy_book if x is not None]
                    if not buy_book:
                        break

                    best_buy = buy_book[0]
                    buy_price, buy_arrival, buy_id, buy_qty = best_buy

                    if order_type == 'market' or price <= buy_price:
                        trade_qty = min(qty, buy_qty)
                        trades.append([buy_id, order_id, buy_price, trade_qty])
                        qty -= trade_qty

                        if trade_qty == buy_qty:
                            buy_book.pop(0)
                            order_map[buy_id] = ('buy', None)
                        else:
                            buy_book[0] = (buy_price, buy_arrival, buy_id, buy_qty - trade_qty)
                    else:
                        break

                # Rest remaining quantity if limit order
                if qty > 0 and order_type == 'limit':
                    book_index = len(sell_book)
                    sell_book.append((price, arrival_time, order_id, qty))
                    order_map[order_id] = ('sell', book_index)
                    # Sort by price (ascending), then by arrival time (ascending)
                    sell_book.sort(key=lambda x: (x[0], x[1]))
                    # Update indices in order_map
                    for i, entry in enumerate(sell_book):
                        if entry is not None:
                            order_map[entry[2]] = ('sell', i)

    return trades

